tasks.solution:
def is_long(password):
    return len(password) >= 8


def has_digit(password):
    for ch in password:
        if ch in "0123456789":
            return True
    return False


def has_upper(password):
    for ch in password:
        if "A" <= ch <= "Z":
            return True
    return False


def password_strength(password):
    score = 0
    if is_long(password):
        score = score + 1
    if has_digit(password):
        score = score + 1
    if has_upper(password):
        score = score + 1
    if score == 3:
        return "сильный"
    if score == 2:
        return "средний"
    return "слабый"
